import React from 'react';

const QuestionCard = ({ index, rowData, options, shouldMask, onUpdate }) => {
  // Safety check: if rowData is missing, don't crash the app
  if (!rowData) return null;

  const isInvalid = rowData.answerConfirmation && rowData.userAnswer !== rowData.answerConfirmation;

  return (
    <div className="question-row">
      <label className="row-label">Security Question {index + 1}</label>
      
      <select
        className="form-select"
        value={rowData.selectedQuestion}
        onChange={e => onUpdate(index, 'selectedQuestion', e.target.value)}
      >
        <option value="">-- Choose Question --</option>
        {options && options.map((item) => (
          <option key={item.q_id} value={item.question}>
            {item.question}
          </option>
        ))}
      </select>

      <div className="input-flex">
        <input
          className="base-input"
          type={shouldMask ? "password" : "text"}
          placeholder="Answer"
          value={rowData.userAnswer}
          onChange={e => onUpdate(index, 'userAnswer', e.target.value)}
        />
        <input
          className={`base-input ${isInvalid ? 'error-border' : ''}`}
          type={shouldMask ? "password" : "text"}
          placeholder="Confirm"
          value={rowData.answerConfirmation}
          onChange={e => onUpdate(index, 'answerConfirmation', e.target.value)}
        />
      </div>
      {isInvalid && <small className="error-msg">Mismatch detected</small>}
    </div>
  );
};

export default QuestionCard;
